<?php require_once '../../includes/functions.php'; requireLogin(); global $pdo; $search = $_GET['search'] ?? ''; $dept = $_GET['department'] ?? 'all'; $sql = "SELECT e.*, d.name as department_name FROM erp_employees e LEFT JOIN erp_departments d ON e.department_id = d.id WHERE 1=1"; $params = []; if ($search) { $sql .= " AND (e.first_name LIKE ? OR e.last_name LIKE ? OR e.email LIKE ?)"; $searchParam = "%$search%"; $params = [$searchParam, $searchParam, $searchParam]; } if ($dept !== 'all') { $sql .= " AND e.department_id = ?"; $params[] = $dept; } $sql .= " ORDER BY e.first_name ASC"; $stmt = $pdo->prepare($sql); $stmt->execute($params); $employees = $stmt->fetchAll(); $departments = $pdo->query("SELECT * FROM erp_departments ORDER BY name")->fetchAll(); ?>
