    <div class="header"><h1>ðŸ‘¥ Employees</h1><div class="header-actions"><a href="../index.php" class="btn btn-secondary">â† Back</a><a href="create-employee.php" class="btn btn-primary">+ New Employee</a></div></div>
    <div class="container"><div class="card"><div class="card-header"><form method="GET" class="filters"><div class="search-box"><input type="text" name="search" placeholder="Search employees..." value="<?= htmlspecialchars($search) ?>"></div><select name="department" class="filter-select" onchange="this.form.submit()"><option value="all">All Departments</option><?php foreach ($departments as $d): ?><option value="<?= $d['id'] ?>" <?= $dept == $d['id'] ? 'selected' : '' ?>><?= htmlspecialchars($d['name']) ?></option><?php endforeach; ?></select><button type="submit" class="btn btn-primary">Search</button></form></div>
    <table class="table"><thead><tr><th>Name</th><th>Department</th><th>Position</th><th>Email</th><th>Status</th><th>Actions</th></tr></thead><tbody>
    <?php if (empty($employees)): ?><tr><td colspan="6" style="text-align: center; padding: 32px; color: #5f6368;">No employees found.</td></tr><?php else: ?><?php foreach ($employees as $emp): ?><tr><td><div class="employee-cell"><div class="avatar"><?= strtoupper(substr($emp['first_name'], 0, 1) . substr($emp['last_name'], 0, 1)) ?></div><div><div style="font-weight: 500;"><?= htmlspecialchars($emp['first_name'] . ' ' . $emp['last_name']) ?></div><div style="font-size: 0.75rem; color: #5f6368;">Joined <?= date('M Y', strtotime($emp['join_date'])) ?></div></div></div></td><td><?= htmlspecialchars($emp['department_name'] ?? '-') ?></td><td><?= htmlspecialchars($emp['position'] ?? '-') ?></td><td><?= htmlspecialchars($emp['email'] ?? '-') ?></td><td><?php $statusClass = ['active' => 'badge-success', 'terminated' => 'badge-danger', 'resigned' => 'badge-warning', 'on_leave' => 'badge-warning']; ?><span class="badge <?= $statusClass[$emp['status']] ?? 'badge-info' ?>"><?= ucfirst(str_replace('_', ' ', $emp['status'])) ?></span></td><td><a href="edit-employee.php?id=<?= $emp['id'] ?>" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.75rem;">Edit</a></td></tr><?php endforeach; ?><?php endif; ?>
    </tbody></table></div></div>
